ret *= light1_dy * 2.0 + 0.4;
ret = mix(ret, 1.0 , abs(GetBlur3(uv).y-GetBlur1(uv).y)*0.5 + GetBlur1(uv+vec2(dx.y,dy.y)*0.16).z * 2.0);
ret = mix(ret, 1.0 ,GetPixel(uv).z);
